def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0))

    need_now = 0
    if hp <= 2 or no_water_days >= 2:
        need_now = 2
    elif hp <= 4 or no_water_days >= 1:
        need_now = 1

    total_players = 1 + len(alive)
    market_tight = 0
    if supply <= WATER_REQ * 1.4:
        market_tight = 2
    elif supply <= WATER_REQ * 1.8:
        market_tight = 1

    opp_bids = []
    high_threat = 0.0
    mid_threat = 0.0
    desperate_count = 0
    rich_count = 0

    for opp in alive:
        if opp.get('budget', 0) >= 140:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev:
            b = prev.get('bid')
            if b is not None:
                opp_bids.append(float(b))
                if b > high_threat:
                    high_threat = float(b)
                if 40 <= float(b) > mid_threat:
                    mid_threat = float(b)

    base = 16.0
    if market_tight == 1:
        base = 34.0
    elif market_tight == 2:
        base = 52.0

    if need_now == 1:
        base += 14.0
    elif need_now == 2:
        base += 28.0

    base += desperate_count * 3.0
    if rich_count >= 2:
        base += 4.0

    target = base

    if opp_bids:
        if high_threat >= 95:
            if need_now == 2:
                target = max(target, 96.5)
            elif market_tight == 2 and hp > 4:
                target = min(target, 38.0)
            else:
                target = max(target, 61.0)
        elif high_threat >= 75:
            if need_now >= 1 or market_tight >= 1:
                target = max(target, high_threat + 1.5)
            else:
                target = max(target, 42.0)
        elif high_threat >= 45:
            target = max(target, high_threat + 1.2)
        else:
            target = max(target, 28.0)

    if day >= 8:
        target += 6.0
    if day >= 9 and hp <= 4:
        target += 10.0

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if days_left > 0 and hp > 3:
        reserve_floor = min(budget, days_left * 8.0)

    affordable = budget
    if budget > reserve_floor:
        affordable = budget - reserve_floor + min(12.0, reserve_floor * 0.25)

    bid = min(target, budget, affordable)

    if need_now == 2:
        bid = min(max(bid, 72.0), budget)
    elif need_now == 1 and bid < 48.0:
        bid = min(48.0, budget)

    if market_tight == 0 and need_now == 0 and high_threat >= 80:
        bid = min(budget, 22.0)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = DAILY_SALARY * 0.6

    if my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 2:
        bid = DAILY_SALARY * 1.1
    elif my_status['hp'] <= 4:
        bid = DAILY_SALARY * 0.9
    elif my_status['hp'] >= 8 and my_status['no_water_days'] == 0:
        bid = DAILY_SALARY * 0.5

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 4 or my_status['no_water_days'] > 0:
                bid = max(bid, highest_prev_bid + 5.0)
            else:
                bid = max(bid, average_prev_bid + 2.0)
        else:
            bid = max(bid, average_prev_bid + 1.0)

    num_slots = int(day_context['supply'] // WATER_REQ)
    total_competitors = len(alive_opponents) + 1

    if num_slots < total_competitors:
        scarcity_factor = 1.0 + (total_competitors - num_slots) * 0.05
        bid *= scarcity_factor
    elif num_slots > total_competitors + 1:
        bid *= 0.9

    bid = min(bid, my_status['budget'])

    if bid < 1.0 and my_status['budget'] >= 1.0:
        bid = 1.0
    elif bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, bid to ensure enough water for requirement
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are likely available; use for scaling but keep simple
    # supply is in [15,25]; water requirement is 13.
    # If supply barely covers one unit, competition is higher.
    approx_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    if approx_units < 1:
        approx_units = 1

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Strategy:
    # - If yesterday's top bid was very high, competition is fierce: bid just enough.
    # - If my hp is low, bid more aggressively.
    # - Otherwise, bid mid-range to secure water without burning budget.
    if highest_prev_bid >= 80.0:
        if my_hp > 3.0:
            bid = DAILY_SALARY * 0.35
        else:
            bid = DAILY_SALARY * 0.9
    elif highest_prev_bid >= 60.0:
        if my_hp > 3.0:
            bid = DAILY_SALARY * 0.5
        else:
            bid = DAILY_SALARY * 0.75
    else:
        # Lower observed pressure: keep bid moderate but not too low
        if my_hp > 3.0:
            bid = DAILY_SALARY * 0.55
        else:
            bid = DAILY_SALARY * 0.85

    # Slightly adjust for supply tightness: lower supply => bid a bit more
    if supply <= float(MIN_SUPPLY) + 1e-9:
        bid *= 1.08
    elif supply >= float(MAX_SUPPLY) - 1e-9:
        bid *= 0.98

    # Ensure non-negative and within budget
    if my_budget <= 0.0:
        return 0.0

    if bid > my_budget:
        bid = my_budget

    # Avoid bidding 0 when we still have budget and hp
    if bid < 1.0 and my_hp > 0.0 and my_budget > 1.0:
        bid = min(my_budget, 1.0)

    return float(bid)

