        base_bid = DAILY_SALARY * 0.65  # 52
    else:
        base_bid = DAILY_SALARY * 0.5   # 40
    # Adjust for HP: if low, bid higher
    if hp <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)  # at least 72
    elif hp <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.75) # at least 60
    # Check yesterday's opponent max bid via previous_trace
    max_prev_bid = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            prev = opp.get('previous_trace', {})
            if prev and 'bid' in prev and prev['bid'] is not None:
                max_prev_bid = max(max_prev_bid, prev['bid'])
    # If previous max bid is high, bid just above it if budget allows, else stick to base
    if max_prev_bid > 0 and max_prev_bid > base_bid:
        target = max_prev_bid + 1.5
        # but do not exceed budget or go too high
        if target < DAILY_SALARY * 0.9:
            base_bid = target
        else:
            base_bid = min(target, DAILY_SALARY * 0.95)
    # Final clamp within budget
    bid = min(base_bid, budget)
    # Also ensure we don't bid more than necessary to win; but we don't know others' bids
    # If supply is very high, reduce bid to save budget
    if supply >= 24 and hp > 4:
        bid = min(bid, DAILY_SALARY * 0.4)
    return int(bid)

